export interface QimeiOptions {
    appKey: string;
    appVersion?: string;
    /** Optional on Windows; if omitted, the bundled qimei.dll is used. Ignored on macOS. */
    dllPath?: string;
    /** Optional for locating native bindings */
    bindingsDir?: string;
}

export default class QimeiSdk {
    constructor(options: QimeiOptions);
    getVersion(): string;
    getQimei36(): Promise<string>;
    getQimei32(): Promise<string>;
    getUskey(busId: string, busInfos?: string | Record<string, string>): Promise<string>;
}
